-- ──────────────────────────────────────────────────────────────────────────
-- Migration 000001: Initial schema (Layer 0)
-- Property Finder OBS-Style
--
-- Conventions (see docs/spec/00_infrastructure_setup/00-02-database-schema.md):
--   • PKs are UUID, generated by the DB via gen_random_uuid()
--   • timestamps are TIMESTAMPTZ (UTC)
--   • no soft delete — hard delete only (search_profile.archived_at is a
--     visibility flag, not a soft delete: rows are never excluded from FKs)
--   • enums are PostgreSQL ENUM types
--   • table names are singular snake_case
--
-- Tables/columns are split into two groups per the schema doc:
--   • carried over unchanged from dev-property-finder (search_profile base
--     columns, criterion, listing base columns, listing_criterion_grade,
--     listing_image base columns, listing_note, app_config, task)
--   • new or changed for this project (context*, chat_*, and the new listing
--     / listing_image / search_profile columns)
-- `profile_proposal` is intentionally NOT carried over — replaced by chat
-- confirmations (ADR 0004, 0009).
-- ──────────────────────────────────────────────────────────────────────────

CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- ── Enums ────────────────────────────────────────────────────────────────

-- Carried over unchanged.
DO $$ BEGIN
    CREATE TYPE listing_status AS ENUM (
        'new',
        'waiting',
        'in_negotiation',
        'visited',
        'rejected',
        'archived'
    );
EXCEPTION
    WHEN duplicate_object THEN NULL;
END $$;

-- Carried over unchanged.
DO $$ BEGIN
    CREATE TYPE criterion_grade AS ENUM (
        'A', 'B', 'C', 'D', 'E', 'F'
    );
EXCEPTION
    WHEN duplicate_object THEN NULL;
END $$;

-- New.
DO $$ BEGIN
    CREATE TYPE chat_role AS ENUM (
        'user', 'assistant', 'tool'
    );
EXCEPTION
    WHEN duplicate_object THEN NULL;
END $$;

-- New.
DO $$ BEGIN
    CREATE TYPE context_scope AS ENUM (
        'global', 'profile'
    );
EXCEPTION
    WHEN duplicate_object THEN NULL;
END $$;

-- New.
DO $$ BEGIN
    CREATE TYPE source_type AS ENUM (
        'url', 'pdf', 'image', 'manual'
    );
EXCEPTION
    WHEN duplicate_object THEN NULL;
END $$;

-- ── search_profile ──────────────────────────────────────────────────────
-- Base columns carried over unchanged. `description` keeps its original
-- NOT NULL constraint but gains a DEFAULT '' — spec 01-08 makes description
-- optional at creation time, unlike dev-property-finder where it drove an
-- immediate AI parse.
CREATE TABLE search_profile (
    id              UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    name            TEXT        NOT NULL,
    description     TEXT        NOT NULL DEFAULT '',
    archived_at     TIMESTAMPTZ,
    ranking_summary TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
-- Carried over: case-insensitive uniqueness on name.
CREATE UNIQUE INDEX uq_search_profile_name_lower ON search_profile (LOWER(name));

-- ── criterion ────────────────────────────────────────────────────────────
-- Carried over unchanged.
CREATE TABLE criterion (
    id            UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    profile_id    UUID        NOT NULL REFERENCES search_profile(id) ON DELETE CASCADE,
    name          TEXT        NOT NULL,
    description   TEXT        NOT NULL,
    weight        INTEGER     NOT NULL DEFAULT 1 CHECK (weight BETWEEN 1 AND 5),
    is_subjective BOOLEAN     NOT NULL,
    sort_order    INTEGER     NOT NULL DEFAULT 0,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX idx_criterion_profile_id ON criterion (profile_id);

-- ── listing ──────────────────────────────────────────────────────────────
-- Base columns carried over unchanged, plus the new columns from 00-02
-- (document_md, source_type, source_file_path, user_confirmed_fields,
-- needs_reevaluation, kurzfazit). `title_image_id` is added via ALTER TABLE
-- below, after listing_image exists — listing and listing_image reference
-- each other, so one side has to be created first without the FK.
CREATE TABLE listing (
    id                    UUID             PRIMARY KEY DEFAULT gen_random_uuid(),
    profile_id            UUID             NOT NULL REFERENCES search_profile(id) ON DELETE CASCADE,
    title                 TEXT             NOT NULL,
    source_url            TEXT,
    price                 NUMERIC,
    price_currency        TEXT,
    property_size_m2      NUMERIC,
    plot_size_m2          NUMERIC,
    address               TEXT,
    region                TEXT,
    country               TEXT,
    latitude              DOUBLE PRECISION,
    longitude             DOUBLE PRECISION,
    description           TEXT,
    title_image_path      TEXT,
    status                listing_status   NOT NULL DEFAULT 'new',
    rejection_comment     TEXT,
    overall_score         NUMERIC(5, 2),
    seller_name           TEXT,
    seller_phone          TEXT,
    seller_email          TEXT,
    seller_notes          TEXT,
    last_contact_at       TIMESTAMPTZ,
    document_md           TEXT,
    source_type           source_type      NOT NULL DEFAULT 'manual',
    source_file_path      TEXT,
    user_confirmed_fields TEXT[]           NOT NULL DEFAULT '{}',
    needs_reevaluation    BOOLEAN          NOT NULL DEFAULT false,
    kurzfazit             TEXT,
    created_at            TIMESTAMPTZ      NOT NULL DEFAULT NOW(),
    updated_at            TIMESTAMPTZ      NOT NULL DEFAULT NOW()
);
-- Dedup within a profile: only rows with a source_url participate; manual
-- entries without a URL are exempt.
CREATE UNIQUE INDEX uq_listing_profile_source_url
    ON listing (profile_id, source_url)
    WHERE source_url IS NOT NULL;
CREATE INDEX idx_listing_profile_id    ON listing (profile_id);
CREATE INDEX idx_listing_status        ON listing (status);
CREATE INDEX idx_listing_overall_score ON listing (overall_score);

-- ── listing_image ────────────────────────────────────────────────────────
-- Base columns (url, is_local, sort_order) carried over unchanged; file_path
-- and category are new (ADR 0012).
CREATE TABLE listing_image (
    id         UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    listing_id UUID        NOT NULL REFERENCES listing(id) ON DELETE CASCADE,
    url        TEXT        NOT NULL,
    is_local   BOOLEAN     NOT NULL DEFAULT false,
    sort_order INTEGER     NOT NULL DEFAULT 0,
    file_path  TEXT        NOT NULL,
    category   TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX idx_listing_image_listing_id ON listing_image (listing_id);

-- Closes the circular FK between listing and listing_image (ADR 0012).
ALTER TABLE listing
    ADD COLUMN title_image_id UUID REFERENCES listing_image(id) ON DELETE SET NULL;

-- ── listing_criterion_grade ──────────────────────────────────────────────
-- Carried over unchanged.
CREATE TABLE listing_criterion_grade (
    id           UUID            PRIMARY KEY DEFAULT gen_random_uuid(),
    listing_id   UUID            NOT NULL REFERENCES listing(id)   ON DELETE CASCADE,
    criterion_id UUID            NOT NULL REFERENCES criterion(id) ON DELETE CASCADE,
    grade        criterion_grade NOT NULL,
    reasoning    TEXT,
    created_at   TIMESTAMPTZ     NOT NULL DEFAULT NOW(),
    UNIQUE (listing_id, criterion_id)
);
CREATE INDEX idx_listing_criterion_grade_listing_id ON listing_criterion_grade (listing_id);

-- ── listing_note ─────────────────────────────────────────────────────────
-- Carried over unchanged.
CREATE TABLE listing_note (
    id         UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    listing_id UUID        NOT NULL REFERENCES listing(id) ON DELETE CASCADE,
    content    TEXT        NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX idx_listing_note_listing_id ON listing_note (listing_id);

-- ── app_config ───────────────────────────────────────────────────────────
-- Carried over unchanged. Tier-2 key-value store (llm.*, geocoding.*, ...).
CREATE TABLE app_config (
    key        TEXT        PRIMARY KEY,
    category   TEXT        NOT NULL,
    value      TEXT        NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX idx_app_config_category ON app_config (category);

-- ── task ─────────────────────────────────────────────────────────────────
-- Carried over unchanged (structure only). The old schema's
-- uq_task_queued_profile_evaluate index encoded a dev-property-finder task
-- type ("profile.evaluate") that has no equivalent here yet — this project's
-- task types (bulk re-evaluation, Layer 2.3; chat SSE, Layer 6.3) are
-- introduced later, so type-specific coalescing indexes are deferred to
-- whichever migration first defines them instead of being guessed now.
CREATE TABLE task (
    id           UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    type         TEXT        NOT NULL,
    status       TEXT        NOT NULL DEFAULT 'queued',
    profile_id   UUID        REFERENCES search_profile(id) ON DELETE CASCADE,
    listing_id   UUID        REFERENCES listing(id)        ON DELETE CASCADE,
    total        INTEGER,
    done         INTEGER     NOT NULL DEFAULT 0,
    failed_count INTEGER     NOT NULL DEFAULT 0,
    error        TEXT,
    payload      JSONB       NOT NULL DEFAULT '{}'::jsonb,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    started_at   TIMESTAMPTZ,
    finished_at  TIMESTAMPTZ,
    updated_at   TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
-- Worker "next queued" lookup: oldest queued first (FIFO).
CREATE INDEX idx_task_status_created_at ON task (status, created_at);
CREATE INDEX idx_task_profile_id        ON task (profile_id);
CREATE INDEX idx_task_listing_id        ON task (listing_id);

-- ── context ──────────────────────────────────────────────────────────────
-- New. Holds both the single Global Context and every Profile Context.
CREATE TABLE context (
    id          UUID          PRIMARY KEY DEFAULT gen_random_uuid(),
    scope       context_scope NOT NULL,
    profile_id  UUID          REFERENCES search_profile(id) ON DELETE CASCADE,
    content_md  TEXT          NOT NULL DEFAULT '',
    created_at  TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
    updated_at  TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
    CONSTRAINT chk_context_scope_profile CHECK (
        (scope = 'global' AND profile_id IS NULL) OR
        (scope = 'profile' AND profile_id IS NOT NULL)
    )
);
-- Exactly one Profile Context per profile.
CREATE UNIQUE INDEX uq_context_profile_id ON context (profile_id) WHERE scope = 'profile';
-- Exactly one Global Context row app-wide.
CREATE UNIQUE INDEX uq_context_global ON context ((true)) WHERE scope = 'global';

-- Seed the single Global Context row so app-wide defaults have somewhere to
-- live from the first migration onward (spec: "seeded on first migration").
-- The actual default text (image-extraction approach, table format,
-- star-rating convention) is filled in by Layer 0.2's config bootstrap, not
-- here — this only guarantees the row exists.
INSERT INTO context (scope, profile_id, content_md) VALUES ('global', NULL, '');

-- ── chat_session ─────────────────────────────────────────────────────────
-- New. One row per Search Profile per "session" (a profile can have several
-- over time; at most one active).
CREATE TABLE chat_session (
    id                    UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    profile_id            UUID        NOT NULL REFERENCES search_profile(id) ON DELETE CASCADE,
    created_at            TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at            TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    ended_at              TIMESTAMPTZ,
    token_count_estimate  INTEGER
);
-- At most one active session per profile.
CREATE UNIQUE INDEX uq_chat_session_active_profile ON chat_session (profile_id) WHERE ended_at IS NULL;

-- ── chat_message ─────────────────────────────────────────────────────────
-- New.
CREATE TABLE chat_message (
    id               UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id       UUID        NOT NULL REFERENCES chat_session(id) ON DELETE CASCADE,
    role             chat_role   NOT NULL,
    content          TEXT        NOT NULL,
    tool_calls       JSONB,
    tool_result      JSONB,
    tool_name        TEXT,
    attachment_path  TEXT,
    listing_id       UUID        REFERENCES listing(id) ON DELETE SET NULL,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX idx_chat_message_session_id_created_at ON chat_message (session_id, created_at);
CREATE INDEX idx_chat_message_listing_id            ON chat_message (listing_id);

-- ── context_revision ─────────────────────────────────────────────────────
-- New. Append-only audit log; created after chat_message so its FK to it
-- can be declared inline.
CREATE TABLE context_revision (
    id              UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    context_id      UUID        NOT NULL REFERENCES context(id) ON DELETE CASCADE,
    content_md      TEXT        NOT NULL,
    changed_by      TEXT        NOT NULL,
    chat_message_id UUID        REFERENCES chat_message(id) ON DELETE SET NULL,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX idx_context_revision_context_id_created_at ON context_revision (context_id, created_at);
